defmodule BaseConv do
  def to_bin(n), do: Integer.to_string(n, 2)
  def to_hex(n), do: Integer.to_string(n, 16)
  def from_bin(s), do: String.to_integer(s, 2)
  def from_hex(s), do: String.to_integer(s, 16)
end

IO.puts(BaseConv.to_bin(255))
IO.puts(BaseConv.to_hex(255))
IO.puts(BaseConv.from_bin("1010"))
IO.puts(BaseConv.from_hex("ff"))

